import{_ as a,o as r,c as t,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 1 章 初识 momawork-rs（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第1章 初识 momawork-rs（易懂版）.md","filePath":"easy/第1章 初识 momawork-rs（易懂版）.md"}'),s={name:"easy/第1章 初识 momawork-rs（易懂版）.md"};function l(n,o,i,h,d,c){return r(),t("div",null,[...o[0]||(o[0]=[e('<h1 id="第-1-章-初识-momawork-rs-易懂版" tabindex="-1">第 1 章 初识 momawork-rs（易懂版） <a class="header-anchor" href="#第-1-章-初识-momawork-rs-易懂版" aria-label="Permalink to &quot;第 1 章 初识 momawork-rs（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 1 章 初识 momawork-rs（完整版）](../../bluebook/第一篇 使用手册：先把我用起来/第 1 章 初识 momawork-rs.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>我是谁、能干啥、不能干啥——5 分钟认识我这个&quot;新同事&quot;。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>把我当成一个<strong>新来的同事</strong>，坐在你电脑旁边干活：</p><ul><li>他不会读心术——<strong>你说什么，他听什么</strong>；</li><li>他不会自己乱跑——<strong>你让他干活，他才干活</strong>；</li><li>他干活很快——但<strong>偶尔出错，需要你检查</strong>；</li><li>他用得越久越懂你——<strong>会记住你的习惯和偏好</strong>。</li></ul><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>我能动手，不只动嘴</strong>：普通聊天机器人只回你文字；我会真的读写你的文件、跑命令、调工具。</li><li><strong>我有八大能力</strong>：写文档、写代码、整理文件、分析数据、管知识、收信息、跑流程、叫帮手——单独用或组合用都行。</li><li><strong>我有边界</strong>：不会读心、看不见你整个电脑（只在你给的工作区干活）、不能随便上网、不是 100% 对。</li></ol><h2 id="一次-ai-任务是怎么跑完的" tabindex="-1">一次 AI 任务是怎么跑完的？ <a class="header-anchor" href="#一次-ai-任务是怎么跑完的" aria-label="Permalink to &quot;一次 AI 任务是怎么跑完的？&quot;">​</a></h2><p>记住这个 5 步循环，以后所有任务都长这样：</p><p><strong>你提需求 → 我理解 → 我调工具干活 → 你检查 → 我交付</strong></p><p>每一步都需要你参与一点点，特别是&quot;检查&quot;——这是防止出错的关键。</p><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;帮我把桌面上的 <code>周报.txt</code> 整理成表格，按日期排序，存成 <code>周报整理.xlsx</code>。&quot;</p><p><strong>你会看到</strong>：我真的打开文件 → 读内容 → 整理 → 生成 Excel → 告诉你放在哪了。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 把它当搜索引擎——问一句答一句，没有下文，你会失望；</li><li>❌ 不看结果就收下——重要的事一定要检查；</li><li>❌ 期望它读心——需求说得越清楚，结果越好。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>不是魔法，是一个很勤快、有点聪明、需要你带的新同事。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>问自己：<strong>&quot;我该把它当搜索引擎，还是当新同事？&quot;</strong> 答案是——<strong>当新同事</strong>。毕业！🎓</p><p>👉 [下一章：第一次对话，把需求讲清楚（易懂版）](第2章 第一次对话：把需求讲清楚（易懂版）.md)</p>',22)])])}const p=a(s,[["render",l]]);export{u as __pageData,p as default};
